INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, sentences) VALUES ('EA3rwvr99Q0', '[{"n":1,"start":0,"end":18,"parts":[{"zh":"啊!"},{"zh":"我才离开几天!"},{"zh":"你们怎么就都没了呀!"},{"zh":"没你们我可怎么我啊!"}],"pinyin":"Á! Wǒ cái líkāi jǐ tiān! Nǐmen zěnme jiù dōu méi le ya! Méi nǐmen wǒ kě zěnme wǒ a!","vi":"Á! Mình mới đi có mấy hôm thôi mà! Sao các cậu lại thế này? Không có các cậu mình biết làm sao bây giờ!"},{"n":2,"start":18,"end":28,"parts":[{"zh":"电子遗言?"},{"zh":"这么高级啊?"}],"pinyin":"Diànzǐ yíyán? Zhème gāojí a?","vi":"Di chúc điện tử? Cao cấp vậy cơ à?"},{"n":3,"start":28,"end":50,"parts":[{"zh":"我是妾女幽魂。"},{"zh":"你是我的命采臣。"},{"zh":"快来吧!"},{"zh":"我的玉帝哥哥!"}],"pinyin":"Wǒ shì qiè nǚ yōuhún. Nǐ shì wǒ de mìng cǎichén. Kuài lái ba! Wǒ de Yùdì gēge!","vi":"Ta là oán hồn của một nàng thiếp. Còn ngươi là người định mệnh của ta. Đến đây đi! Anh trai Ngọc Hoàng của ta!"},{"n":4,"start":50,"end":56,"parts":[{"zh":"啊!"},{"zh":"我的妈呀!"}],"pinyin":"Á! Wǒ de māya!","vi":"Á! Mẹ ơi!"},{"n":5,"start":56,"end":72,"parts":[{"zh":"退!"},{"zh":"退!"},{"zh":"退!"},{"zh":"退!"},{"zh":"退!"},{"zh":"退!"},{"zh":"退!"},{"zh":"退!"}],"pinyin":"Tuì! Tuì! Tuì! Tuì! Tuì! Tuì! Tuì! Tuì!","vi":"Lùi! Lùi! Lùi! Lùi! Lùi! Lùi! Lùi! Lùi!"},{"n":6,"start":72,"end":78,"parts":[{"zh":"惊喜?"}],"pinyin":"Jīngxǐ?","vi":"Bất ngờ à?"},{"n":7,"start":78,"end":90,"parts":[{"zh":"师傅,"},{"zh":"十万元。"}],"pinyin":"Shīfu, shíwàn yuán.","vi":"Sư phụ, một trăm ngàn tệ."},{"n":8,"start":90,"end":104,"parts":[{"zh":"哦?"},{"zh":"哎呀呀呀呀呀呀呀呀!"}],"pinyin":"Ó? Āiyā yā yā yā yā yā yā ya!","vi":"Ôi? A a a a a a a a!"},{"n":9,"start":104,"end":165,"parts":[{"zh":"跟你说了多少遍了?"},{"zh":"不要乱扫二文码!"},{"zh":"不要乱扫二文码!"}],"pinyin":"Gēn nǐ shuōle duōshao biàn le? Bùyào luàn sǎo èrwén mǎ! Bùyào luàn sǎo èrwén mǎ!","vi":"Mình đã bảo cậu bao nhiêu lần rồi? Đừng có quét mã QR bừa bãi! Đừng quét mã QR bừa bãi!"}]');
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, sentences) VALUES ('sXo-yHFkAio', '[{"n":1,"start":0,"end":10,"parts":[{"zh":"老板，"},{"zh":"这苹果怎么卖?"}],"pinyin":"Lǎobǎn, zhè píngguǒ zěnme mài?","vi":"Bác chủ, táo này bán thế nào ạ?"},{"n":2,"start":10,"end":18,"parts":[{"zh":"五块一斤，"},{"zh":"很甜。"}],"pinyin":"Wǔ kuài yī jīn, hěn tián.","vi":"Năm tệ một cân, ngọt lắm."},{"n":3,"start":18,"end":27,"parts":[{"zh":"太贵了，"},{"zh":"三块行不行?"}],"pinyin":"Tài guì le, sān kuài xíng bu xíng?","vi":"Đắt quá, ba tệ được không?"},{"n":4,"start":27,"end":38,"parts":[{"zh":"这是进口苹果，"},{"zh":"一分都不能少。"}],"pinyin":"Zhè shì jìnkǒu píngguǒ, yīfēn dōu bùnéng shǎo.","vi":"Đây là táo nhập khẩu, một phân cũng không giảm được."},{"n":5,"start":38,"end":50,"parts":[{"zh":"那我买一个"},{"zh":"总可以吧?"}],"pinyin":"Nà wǒ mǎi yīgè zǒng kěyǐ ba?","vi":"Vậy tôi mua một quả chắc được chứ?"},{"n":6,"start":50,"end":66,"parts":[{"zh":"一个也五块，"},{"zh":"不讲价。"}],"pinyin":"Yīgè yě wǔ kuài, bù jiǎngjià.","vi":"Một quả cũng năm tệ, không mặc cả."}]');
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, sentences) VALUES ('H3aRI3ypx_0', '[{"n":1,"start":0,"end":14,"parts":[{"zh":"大家好，"},{"zh":"欢迎来到我的频道。"}],"pinyin":"Dàjiā hǎo, huānyíng lái dào wǒ de píndào.","vi":"Chào mọi người, chào mừng đến với kênh của mình."},{"n":2,"start":14,"end":30,"parts":[{"zh":"今天我们一起学习"},{"zh":"怎么打招呼。"}],"pinyin":"Jīntiān wǒmen yīqǐ xuéxí zěnme dǎ zhāohu.","vi":"Hôm nay chúng ta cùng học cách chào hỏi."},{"n":3,"start":30,"end":48,"parts":[{"zh":"你好，"},{"zh":"你叫什么名字?"}],"pinyin":"Nǐ hǎo, nǐ jiào shénme míngzi?","vi":"Xin chào, bạn tên là gì?"},{"n":4,"start":48,"end":64,"parts":[{"zh":"我叫安娜，"},{"zh":"你呢?"}],"pinyin":"Wǒ jiào Ānnà, nǐ ne?","vi":"Mình tên là Anna, còn bạn?"},{"n":5,"start":64,"end":82,"parts":[{"zh":"很高兴认识你!"}],"pinyin":"Hěn gāoxìng rènshi nǐ!","vi":"Rất vui được gặp bạn!"},{"n":6,"start":82,"end":100,"parts":[{"zh":"我也很高兴认识你!"}],"pinyin":"Wǒ yě hěn gāoxìng rènshi nǐ!","vi":"Mình cũng rất vui được gặp bạn!"}]');
INSERT OR REPLACE INTO content_shadowing_subtitles (video_id, sentences) VALUES ('DQBzSl3OM1I', '[{"n":1,"start":0,"end":16,"parts":[{"zh":"大家好，"},{"zh":"欢迎回到简单生活。"}],"pinyin":"Dàjiā hǎo, huānyíng huídào jiǎndān shēnghuó.","vi":"Chào mọi người, chào mừng quay lại với 简单生活."},{"n":2,"start":16,"end":34,"parts":[{"zh":"今天我想聊聊"},{"zh":"我的周末。"}],"pinyin":"Jīntiān wǒ xiǎng liáoliáo wǒ de zhōumò.","vi":"Hôm nay mình muốn nói về cuối tuần của mình."},{"n":3,"start":34,"end":56,"parts":[{"zh":"星期六早上，"},{"zh":"我去市场买了新鲜的蔬菜。"}],"pinyin":"Xīngqīliù zǎoshang, wǒ qù shìchǎng mǎile xīnxiān de shūcài.","vi":"Sáng thứ bảy, mình ra chợ mua rau tươi."},{"n":4,"start":56,"end":78,"parts":[{"zh":"下午，"},{"zh":"我和朋友在咖啡馆聊了两个小时。"}],"pinyin":"Xiàwǔ, wǒ hé péngyou zài kāfēiguǎn liáole liǎng gè xiǎoshí.","vi":"Buổi chiều, mình và bạn bè trò chuyện ở quán cà phê hai tiếng đồng hồ."},{"n":5,"start":78,"end":102,"parts":[{"zh":"晚上我看了一部"},{"zh":"很有意思的电影。"}],"pinyin":"Wǎnshang wǒ kànle yī bù hěn yǒuyìsi de diànyǐng.","vi":"Tối mình xem một bộ phim rất thú vị."},{"n":6,"start":102,"end":126,"parts":[{"zh":"你的周末"},{"zh":"是怎么过的呢?"}],"pinyin":"Nǐ de zhōumò shì zěnme guò de ne?","vi":"Cuối tuần của bạn được trải qua như thế nào?"}]');
